{
  "technical_and_design_decisions": [
    "U1: Implement per-transaction context in Java chaincode shim by creating a new Context object per transaction invocation, passed to contract methods to ensure thread-safety without sacrificing performance.",
    "U2/U3: Treat U2 and U3 as the same task (duplicate user story). Perform a single package move from protos/utils to protoutils, updating all import references and regenerating any Go/Java bindings.",
    "U4: Backport Kafka orderer health checks by cherry-picking the relevant commits from master into the 1.4 LTS branch, resolving any merge conflicts and adapting for LTS differences.",
    "U5: Introduce an explicit read-only Invoke API in the chaincode shim (rather than inferring read-only behavior from Puts/Gets), and relax the access-control check in the endorser so channel Readers can invoke read-only chaincodes.",
    "U6: Add a new peer configuration option (e.g., CORE_PEER_GOSSIP_EXTERNAL_ENDPOINT for Service Discovery) that is advertised independently of the gossip endpoint, allowing Docker-network peers to be discovered without a DNS.",
    "U7: Extend the operations service proto with a new GetVersion RPC and implement the handler on both peer and orderer to return the running binary version.",
    "U8: Refactor existing Go chaincode samples using idiomatic Go (clearer package layout, better error handling, concise comments) and add at least one end-to-end beginner-friendly sample."
  ],
  "assumptions": [
    "The implementer is a senior developer familiar with the Hyperledger Fabric (Go and Java) codebases.",
    "All work is performed by a single developer; no team coordination overhead is added beyond self-review.",
    "U2 and U3 are duplicates; the refactor is done once.",
    "Local unit and integration tests are sufficient; no full multi-org network test environment setup is required beyond what is already available.",
    "Proto regeneration and dependency bumps are handled as part of the related activities (no separate estimate).",
    "No database migrations or data backfill are required for any of the changes.",
    "Documentation updates for the new features are included as a single consolidated activity.",
    "Effort estimates include coding, self-review, and local testing but not external CI runs or release management."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Java chaincode transactional context (U1)",
      "activity_description": "Refactor the Java chaincode shim so that each transaction gets its own Context object exposing the stub and APIs; update contract base class and existing Java chaincode samples; add unit tests covering thread-safety.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A2",
      "activity_name": "Move protos/utils to protoutils (U2/U3)",
      "activity_description": "Relocate the protos/utils package to a new top-level protoutils package, update all import references across the Go and Java codebases, regenerate proto bindings if needed, and run the build to verify.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A3",
      "activity_name": "Backport Kafka health checks to 1.4 LTS (U4)",
      "activity_description": "Identify the Kafka health-check commits on master, port them to the 1.4 LTS branch, resolve conflicts, and add regression tests against a Kafka-based orderer setup.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A4",
      "activity_name": "Allow channel Readers to invoke query chaincode (U5)",
      "activity_description": "Add a read-only Invoke entry point in the chaincode shim for both Go and Java, relax the endorser access-control check so channel Readers can call it, and extend integration tests to cover Reader-role query invocations.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5",
      "activity_name": "Explicit external endpoint for Service Discovery (U6)",
      "activity_description": "Add a new peer config option for the Service Discovery external endpoint, wire it through the discovery service response, and update SDK-facing docs/samples; add tests that verify the advertised endpoint.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6",
      "activity_name": "Operations service GetVersion endpoint (U7)",
      "activity_description": "Extend the operations proto with a GetVersion RPC, implement the handler on both peer and orderer servers, regenerate bindings, and add unit tests for both implementations.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A7",
      "activity_name": "Refactor Go chaincode samples (U8)",
      "activity_description": "Review existing Go chaincode samples, rewrite them in idiomatic Go with clearer structure and beginner-friendly comments, and add at least one minimal end-to-end sample to the fabric-samples repository.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A8",
      "activity_name": "Cross-feature integration testing",
      "activity_description": "Run end-to-end test suites covering the combined changes (query-only chaincode, version endpoint, discovery endpoint, backported health checks) against a local multi-org network.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A9",
      "activity_name": "Documentation updates",
      "activity_description": "Update release notes, concept/feature docs, and sample READMEs to describe the new transactional context, read-only invoke, external discovery endpoint, version endpoint, and refreshed Go samples.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A10",
      "activity_name": "Self-review and rework buffer",
      "activity_description": "Self code review, addressing review comments, and minor rework across all changes before submission.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 122
  }
}
